args.source:
import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "context-note",
  name: "Context Note",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "context",
      context: {
        id: "task-note",
        contentFn: () => "材料编号 CTX-7319",
      },
    });

    ctx.register({
      kind: "tool",
      tool: {
        name: "context_ready",
        version: "1.0.0",
        description: "检查任务材料上下文是否就绪",
        permissions: [],
        sideEffect: false,
        parameters: { type: "object", properties: {}, additionalProperties: false },
        outputSchema: { type: "object", properties: { ready: { type: "boolean" } }, required: ["ready"] },
        async handler(_args, _tctx) {
          return { ok: true, data: { ready: true } };
        },
      },
    });
  },
};

export default plugin;

